export const getAeTemplate = id => AE_TEMPLATES.find(template => template.id === id);

export const applyAeTemplate = (scene, id, originalTexts = false) => {
  const template = getAeTemplate(id);
  if (!template) return scene;
  const titles = template.texts.filter(text => text.name.startsWith('Zeile_'));
  const text = name => template.texts.find(entry => entry.name === name);
  const date = text('Wochentag_Datum'), meta = text('Start_Dauer');
  const email = text('Anmeldung'), location = text('Ort_Raum');
  const { width, height } = template;
  return {
    ...scene, aeTemplateId: id, presetId: template.format, motionPresetId: 'ae-original',
    infoLayoutPresetId: 'ae-original', colorPresetId: 'schwarz-weiss', useCustomBackground: false,
    playback: { ...scene.playback, duration: 15, fps: 30, rate: 1, time: 0 },
    mask: { ...scene.mask, presetId: template.maskPresetId, aeMotionId: template.motionId, aeStatic: template.staticMask,
      maskSrc: `./masks/${template.maskPresetId.startsWith('post') ? 'Post' : 'Story'}_Form_${template.maskPresetId.slice(-2)}.png`,
      aeFlipX: Math.sign(template.mask.scale[0]), aeFlipY: Math.sign(template.mask.scale[1]),
      shapeScale: 1, squishX: 1, squishY: 1, xOffset: 0, yOffset: 0, breath: 0 },
    stage: { ...scene.stage, x: template.mask.position[0] / width, y: template.mask.position[1] / height,
      width: Math.abs(template.mask.scale[0]) / 100, height: Math.abs(template.mask.scale[1]) / 100,
      rotation: template.mask.rotation, scale: 1, showBackdrop: false },
    imageMotion: { ...scene.imageMotion, scale: 1, driftX: 0, driftY: 0, zoom: 0, rotate: 0, orbit: 0 },
    infoLayer: { ...scene.infoLayer, fontFamily: 'Degular', weight: 400, titleWeight: 600,
      titleSize: titles[0].size, dateSize: date.size, metaSize: meta.size, emailSize: email.size, locationSize: location.size,
      titleX: titles[0].x / width, titleY: titles[0].y / height, title2Y: titles[3].y / height,
      titleMaxWidth: titles[0].maxWidth / width, titleLineHeight: titles[0].leading / titles[0].size,
      dateX: date.x / width, dateY: date.y / height, dateAlign: date.align,
      metaX: meta.x / width, metaY: meta.y / height, metaAlign: meta.align,
      emailX: email.x / width, emailY: email.y / height, emailAlign: email.align,
      locationX: location.x / width, locationY: location.y / height, locationAlign: location.align,
      titleColor: '#FFFFFF', dateColor: '#FFFFFF', metaColor: '#FFFFFF', emailColor: '#FFFFFF',
      aeHeaderText: originalTexts ? titles.map(title => title.text).join('\n')
        : (scene.infoLayer.aeHeaderText ?? [scene.infoLayer.title1, '', '', scene.infoLayer.title2, '', ''].join('\n')),
      ...(originalTexts ? { date: date.text, start: meta.text.split('\n')[0], duration: meta.text.split('\n').slice(1).join('\n'),
        email: email.text, location: location.text } : {}),
    },
  };
};
